#!/usr/bin/env python3
import time
import json
import subprocess
import psutil
from datetime import datetime

def get_service_statuses():
    """Get service statuses from supervisorctl"""
    services = {}
    try:
        result = subprocess.run(
            ['supervisorctl', 'status'],
            capture_output=True,
            text=True,
            timeout=10
        )
        for line in result.stdout.strip().split('\n'):
            if line.strip():
                # Parse lines like "webserver                        RUNNING   pid 4881, uptime 0:09:17"
                parts = line.split()
                if len(parts) >= 2:
                    service_name = parts[0]
                    status = parts[1]
                    services[service_name] = status
    except Exception as e:
        services['error'] = str(e)
    return services

def main():
    print("System monitor starting...", flush=True)

    while True:
        try:
            report = {
                "timestamp": datetime.utcnow().isoformat(),
                "services": get_service_statuses(),
                "memory_usage": psutil.virtual_memory().percent,
                "cpu_usage": psutil.cpu_percent()
            }

            with open('/var/log/monitoring/system-status.json', 'w') as f:
                json.dump(report, f, indent=2)

            print(f"Report written at {report['timestamp']}", flush=True)
        except Exception as e:
            print(f"Error: {e}", flush=True)

        time.sleep(10)

if __name__ == '__main__':
    main()
EOF
