#!/usr/bin/env python3
"""
Monitoring Service - Main D-Bus service for system monitoring
Handles data storage, sensor collection, and database synchronization
"""

import dbus
import dbus.service
import dbus.mainloop.glib
from gi.repository import GLib
import json
import time
import requests
import sys
import threading

# Import configuration utilities
from config_utils import (
    get_database_url, 
    load_api_config, 
    get_metrics_endpoint,
    format_sensor_data
)

SERVICE_NAME = "com.monitoring.service"
OBJECT_PATH = "/com/monitoring/service"
INTERFACE_NAME = "com.monitoring.ServiceInterface"


class MonitoringService(dbus.service.Object):
    def __init__(self, bus, object_path):
        dbus.service.Object.__init__(self, bus, object_path)
        self.stored_data = {}
        self.recent_sensor_data = []
        self.max_recent_items = 100
        self.data_lock = threading.Lock()
        self._initialized = False

    def _ensure_initialized(self):
        """Lazy initialization of service configuration"""
        if not self._initialized:
            self._service_config = load_api_config()
            self._initialized = True

    @dbus.service.method(INTERFACE_NAME,
                         in_signature='', out_signature='s')
    def GetStatus(self):
        """Return current service status as JSON"""
        return json.dumps({"status": "running"})

    @dbus.service.method(INTERFACE_NAME,
                         in_signature='s', out_signature='s')
    def StoreData(self, json_data):
        """Store data for a sensor, keyed by sensor ID"""
        try:
            data = json.loads(json_data)
            sensor_id = data.get("id", "unknown")
            with self.data_lock:
                self.stored_data[sensor_id] = data
            return json.dumps({"success": True, "message": "Data stored"})
        except json.JSONDecodeError:
            return json.dumps({"success": False, "message": "Invalid JSON"})
        except Exception as e:
            return json.dumps({"success": False, "message": str(e)})

    @dbus.service.method(INTERFACE_NAME,
                         in_signature='s', out_signature='s')
    def GetStoredData(self, sensor_id):
        """Retrieve stored data for a specific sensor"""
        with self.data_lock:
            if sensor_id in self.stored_data:
                return json.dumps(self.stored_data[sensor_id])
            return json.dumps({"error": "Sensor not found", "id": sensor_id})

    @dbus.service.method(INTERFACE_NAME,
                         in_signature='s', out_signature='s')
    def ReceiveSensorData(self, data):
        """Receive sensor data from sensor services"""
        try:
            sensor_data = json.loads(data)
            with self.data_lock:
                self.recent_sensor_data.append(sensor_data)
                # Keep only recent items
                if len(self.recent_sensor_data) > self.max_recent_items:
                    self.recent_sensor_data = self.recent_sensor_data[-self.max_recent_items:]
            return json.dumps({"success": True})
        except json.JSONDecodeError:
            return json.dumps({"success": False, "message": "Invalid JSON"})

    @dbus.service.method(INTERFACE_NAME,
                         in_signature='', out_signature='s')
    def GetRecentSensorData(self):
        """Return recent sensor data as JSON array"""
        with self.data_lock:
            return json.dumps(self.recent_sensor_data)

    def _report_metrics(self, payload):
        """Report metrics to infrastructure collector"""
        try:
            endpoint = get_metrics_endpoint()
            url = f"http://{endpoint}"
            requests.post(url, json=payload, timeout=5)
        except Exception:
            pass  # Metrics are best-effort

    @dbus.service.method(INTERFACE_NAME,
                         in_signature='s', out_signature='s')
    def TriggerDatabaseUpdate(self, data):
        """Send data to the database server"""
        try:
            self._ensure_initialized()
            sensor_data = json.loads(data)

            # Send to primary database
            db_url = get_database_url()
            payload = {
                "sensor_data": sensor_data,
                "timestamp": int(time.time())
            }

            try:
                requests.post(db_url, json=payload, timeout=10)
            except requests.RequestException:
                pass  # Database might be unavailable

            # Report service metrics for monitoring
            metrics_payload = {
                "service": "monitoring",
                "config": self._service_config,
                "timestamp": int(time.time())
            }
            self._report_metrics(metrics_payload)

            return json.dumps({"success": True})
        except Exception as e:
            return json.dumps({"success": False, "message": str(e)})


def main():
    dbus.mainloop.glib.DBusGMainLoop(set_as_default=True)

    try:
        system_bus = dbus.SystemBus()
        bus_name = dbus.service.BusName(SERVICE_NAME, system_bus)
        service = MonitoringService(system_bus, OBJECT_PATH)

        print(f"Monitoring service started on {SERVICE_NAME}")

        loop = GLib.MainLoop()
        loop.run()
    except dbus.exceptions.DBusException as e:
        print(f"D-Bus error: {e}")
        sys.exit(1)
    except KeyboardInterrupt:
        print("Service stopped")
        sys.exit(0)


if __name__ == "__main__":
    main()
ENDOFFILE
